// Digital glitch blocks over a gradient.
// Blocks shift horizontally and re-randomize uRate times per second.
uniform float uIntensity;  // @param 0.6 0 1
uniform float uRate;       // @param 8.0 1 30
uniform float uBlockSize;  // @param 0.08 0.02 0.3
uniform float uRGBSplit;   // @param 0.5 0 1
uniform vec3  uColorA;     // @param #1A1F6B
uniform vec3  uColorB;     // @param #FF4D8D

vec3 grad(vec2 q) {
  q.x = fract(q.x);
  float t = clamp(q.x * 0.75 + q.y * 0.25, 0.0, 1.0);
  vec3 c = mix(uColorA, uColorB, smoothstep(0.0, 1.0, t));
  c += 0.06 * (1.0 - q.y);
  return c;
}

// Returns horizontal shift and an "active" mask for one block layer.
vec2 blockLayer(vec2 q, float size, float stepId, float seed) {
  float rows = 1.0 / size;
  float ry = floor(q.y * rows);
  float rowR = hash(vec2(ry + seed, stepId));
  float cols = rows * 0.35;
  float cx = floor(q.x * cols + hash(vec2(ry, stepId + seed + 3.0)) * 4.0);
  float cellR = hash(vec2(cx + seed * 2.0, ry + stepId * 7.13));
  float active = step(1.0 - uIntensity * 0.65, rowR) * step(0.4, cellR);
  float shift = (hash(vec2(ry + seed, stepId + 1.7)) - 0.5) * 0.45;
  return vec2(shift * active, active);
}

void main() {
  float stepId = floor(iTime * uRate);
  vec2 q = uv;

  vec2 a = blockLayer(q, uBlockSize, stepId, 0.0);
  vec2 b = blockLayer(q, uBlockSize * 2.7, stepId + 13.0, 41.0);
  float active = max(a.y, b.y);
  float shift = (a.x + b.x * 0.6) * uIntensity;
  q.x += shift;

  float split = uRGBSplit * 0.02 * uIntensity * active
              * (0.5 + hash(vec2(stepId, floor(uv.y / uBlockSize))));
  vec3 col;
  col.r = grad(q + vec2(split, 0.0)).r;
  col.g = grad(q).g;
  col.b = grad(q - vec2(split, 0.0)).b;

  // Occasional block treatments: invert or posterize.
  float fx = hash(vec2(floor(uv.y / uBlockSize), stepId + 5.0));
  if (active > 0.5 && fx > 0.88) col = 1.0 - col;
  else if (active > 0.5 && fx > 0.72) col = floor(col * 4.0) / 4.0;

  // Thin bright tear lines.
  float lineR = hash(vec2(floor(uv.y * iResolution.y / 2.0), stepId));
  col += step(1.0 - 0.015 * uIntensity, lineR) * 0.5;

  // Faint scanlines.
  col *= 1.0 - 0.06 * uIntensity * step(0.5, fract(uv.y * iResolution.y * 0.5));

  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
